CHANGE_TOOL:
{% set temp = params.TEMP|int %}
{% set r_len = params.RETRACT_LEN|default(1.2)|float %}
{% set temp = params.TEMP|int %}
{% set slicer_temp = params.SLICER_TEMP|default(temp)|int %}
{% set r_len = params.RETRACT_LEN|default(1.2)|float %}
SET_GCODE_VARIABLE MACRO=TOOL_STATE VARIABLE=changing VALUE=1
PARK_CURRENT NEXT_TEMP={temp}
SET_GCODE_VARIABLE MACRO=TOOL_STATE VARIABLE=changing VALUE=0
SET_GCODE_VARIABLE MACRO=TOOL_STATE VARIABLE=changing VALUE=1
PARK_CURRENT NEXT_TEMP={slicer_temp}
SET_GCODE_VARIABLE MACRO=TOOL_STATE VARIABLE=changing VALUE=0
{% if next_tool == 0 %}
DOCK_TOOL_0 EXTRUDER_TEMP={temp} FIRST_USE={first_use} H_D={h_d} {prime_p}
{% elif next_tool == 1 %}
DOCK_TOOL_1 EXTRUDER_TEMP={temp} FIRST_USE={first_use} H_D={h_d} {prime_p}
{% elif next_tool == 2 %}
DOCK_TOOL_2 EXTRUDER_TEMP={temp} FIRST_USE={first_use} H_D={h_d} {prime_p}
{% elif next_tool == 3 %}
DOCK_TOOL_3 EXTRUDER_TEMP={temp} FIRST_USE={first_use} H_D={h_d} {prime_p}
{% endif %}
{% if next_tool == 0 %}
DOCK_TOOL_0 EXTRUDER_TEMP={temp} SLICER_TEMP={slicer_temp} FIRST_USE={first_use} H_D={h_d} {prime_p}
{% elif next_tool == 1 %}
DOCK_TOOL_1 EXTRUDER_TEMP={temp} SLICER_TEMP={slicer_temp} FIRST_USE={first_use} H_D={h_d} {prime_p}
{% elif next_tool == 2 %}
DOCK_TOOL_2 EXTRUDER_TEMP={temp} SLICER_TEMP={slicer_temp} FIRST_USE={first_use} H_D={h_d} {prime_p}
{% elif next_tool == 3 %}
DOCK_TOOL_3 EXTRUDER_TEMP={temp} SLICER_TEMP={slicer_temp} FIRST_USE={first_use} H_D={h_d} {prime_p}
{% endif %}

DOCK_TOOL_0:
{% set normal_temp = params.EXTRUDER_TEMP|int %}
{% set preheat_temp = normal_temp + 40 %}
{% set is_175 = 1 if ef|float > 0.9 else 0 %}    # ef = (1.75/dia)**2  →  1.75mm=1.0 / 2.85mm=0.3768

M104 S{preheat_temp}
TEMPERATURE_WAIT SENSOR=extruder MINIMUM={ normal_temp -9 } MAXIMUM={preheat_temp +40}
RESPOND MSG="DOCKING T1."
{% set normal_temp = params.EXTRUDER_TEMP|int %}
{% set slicer_temp = params.SLICER_TEMP|default(normal_temp)|int %}
{% set preheat_temp = normal_temp + 20 %}
{% set is_175 = 1 if ef|float > 0.9 else 0 %}    # ef = (1.75/dia)**2  →  1.75mm=1.0 / 2.85mm=0.3768

# M104 S{preheat_temp}
# TEMPERATURE_WAIT SENSOR=extruder MINIMUM={ normal_temp -9 } MAXIMUM={preheat_temp +40}
RESPOND MSG="DOCKING T1."

{% set preheat_temp = normal_temp + (15 if is_175 else 25) %}
M104 S{preheat_temp}


# M104 S{preheat_temp}


{% set preheat_temp = normal_temp + (10 if is_175 else 12) %}
M104 S{preheat_temp}
TOOLHEAD_DOCK_HEAT TEMP={normal_temp}
FAST_CANCEL_WAIT P={(h_d * 1000)|int}
FAST_CANCEL_PRIME STATE=begin TOOL=0

{% set preheat_temp = normal_temp + (5 if is_175 else 5) %}
# M104 S{preheat_temp}
TOOLHEAD_DOCK_HEAT TEMP={slicer_temp}
# FAST_CANCEL_WAIT P={(h_d * 1000)|int}
TOOLHEAD_WAIT_FOR_PRIME TARGET={slicer_temp}
FAST_CANCEL_PRIME STATE=begin TOOL=0
{% set preheat_temp = normal_temp + (5 if is_175 else 10) %}
M104 S{preheat_temp}
# 2차 프라임: P2 를 MVS 로
{% set preheat_temp = normal_temp %}
# M104 S{preheat_temp}
# 2차 프라임: P2 를 MVS 로
{% set preheat_temp = normal_temp + (2 if is_175 else 2) %}
M104 S{preheat_temp}
# 2차 폼 프라임: FP2 를 MVS 로
{% set preheat_temp = normal_temp %}
# M104 S{preheat_temp}
# 2차 폼 프라임: FP2 를 MVS 로

